using System.Linq;using NUnit.Framework;using UnityEditor.SceneManagement;using UnityEngine;using EternalSteam.OpenWorld;
namespace EternalSteam.Tests{
[Category("CurrentScene")]
public sealed class RailwayOverviewTests{
[Test]

public void OverviewIsAuthoredAndPreservesLegacyControls(){var scene=CurrentSceneFixture.Open();var name=scene.name;try{var h=scene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<CanvasWorldHud>(true)).Single();var v=h.Sandbox.RailwayHud.GetComponent<RailwayOverview>();Assert.That(v,Is.Not.Null);Assert.That(v.Hud,Is.SameAs(h));Assert.That(v.Rows.Length,Is.EqualTo(v.Railway.Rows.Length));Assert.That(v.Root.IsChildOf(h.Groups.Construction.transform),Is.True);Assert.That(v.Root.IsChildOf(v.Legacy.transform),Is.False,"Overview must not inherit invisible legacy CanvasGroup");Assert.That(v.DetailScroll.GetComponent<UnityEngine.UI.ScrollRect>().viewport.GetComponent<UnityEngine.UI.Mask>(),Is.Not.Null);foreach(var row in v.Rows){Assert.That(row.onClick.GetPersistentTarget(0),Is.SameAs(v));Assert.That(row.onClick.GetPersistentMethodName(0),Is.EqualTo("SelectRow"));}foreach(var action in v.Actions){Assert.That(action.Button.onClick.GetPersistentTarget(0),Is.SameAs(v));Assert.That(action.Button.onClick.GetPersistentMethodName(0),Is.EqualTo("Execute"));}Assert.That(v.Actions.Select(a=>a.Command),Is.EquivalentTo(new[]{"new","connect","start","stop","fuel","cargo","defense","edit","cancel-pending"}));Assert.That(v.Root.GetComponentsInChildren<TMPro.TMP_Text>(true).All(t=>!t.enableAutoSizing&&t.fontSize==18),Is.True);Assert.That(v.Railway.Commands.All(c=>c.Button!=null),Is.True);Assert.That(v.LegacyBack.onClick.GetPersistentTarget(0),Is.SameAs(v));}finally{CurrentSceneFixture.Close(scene);}}
}}
